import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"world/Level","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"world/Level"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/prismarine/world/Level/"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/prismarine/world/Level/"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/prismarine/src"}},"headers":[],"relativePath":"api/@jsprismarine/prismarine/world/Level/index.md","filePath":"api/@jsprismarine/prismarine/world/Level/index.md","lastUpdated":1794500225000}`),a={name:`api/@jsprismarine/prismarine/world/Level/index.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../../">API reference</a> / <a href="./../../">@jsprismarine/prismarine</a> / world/Level</p><h1 id="world-level" tabindex="-1">world/Level <a class="header-anchor" href="#world-level" aria-label="Permalink to “world/Level”">​</a></h1><h2 id="classes" tabindex="-1">Classes <a class="header-anchor" href="#classes" aria-label="Permalink to “Classes”">​</a></h2><ul><li><a href="./classes/Level.html">Level</a></li></ul><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to “Interfaces”">​</a></h2><h3 id="leveloptions" tabindex="-1">LevelOptions <a class="header-anchor" href="#leveloptions" aria-label="Permalink to “LevelOptions”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L81" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:81</a></p><p>How a <a href="./classes/Level.html">Level</a> is built.</p><h4 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h4><h5 id="chunkhost" tabindex="-1">chunkHost? <a class="header-anchor" href="#chunkhost" aria-label="Permalink to “chunkHost?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>chunkHost?</strong>: <code>&quot;process&quot;</code> | <code>&quot;in-process&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L115" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:115</a></p><p>Where chunk generation workers run, forwarded to generator factories.</p><h5 id="chunkworkers" tabindex="-1">chunkWorkers? <a class="header-anchor" href="#chunkworkers" aria-label="Permalink to “chunkWorkers?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>chunkWorkers?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L113" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:113</a></p><p>The chunk worker limit from server configuration, forwarded to generator factories.</p><h5 id="config" tabindex="-1">config? <a class="header-anchor" href="#config" aria-label="Permalink to “config?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>config?</strong>: <code>Partial</code>&lt;<code>WorldData</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L119" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:119</a></p><p>The <code>worlds.&lt;name&gt;</code> entry as configured, which a provider may read when generating.</p><h5 id="dimensiontypes" tabindex="-1">dimensionTypes <a class="header-anchor" href="#dimensiontypes" aria-label="Permalink to “dimensionTypes”">​</a></h5><blockquote><p><code>readonly</code> <strong>dimensionTypes</strong>: <code>ReadonlyMap</code>&lt;<code>string</code>, <a href="./../../../worldgen/#dimensiontypedefinition"><code>DimensionTypeDefinition</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L102" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:102</a></p><p>The Java <code>dimension_type</code> definitions the stems may name, keyed by type id. The level resolves each one a stem uses into a DimensionType, handing out Bedrock ids from FIRST_CUSTOM_DIMENSION_ID to the types the overlay does not list.</p><h5 id="factories" tabindex="-1">factories <a class="header-anchor" href="#factories" aria-label="Permalink to “factories”">​</a></h5><blockquote><p><code>readonly</code> <strong>factories</strong>: <a href="./../GeneratorFactories/classes/GeneratorFactories.html"><code>GeneratorFactories</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L106" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:106</a></p><p>The generator kinds this server can build a stem with.</p><h5 id="handlers" tabindex="-1">handlers? <a class="header-anchor" href="#handlers" aria-label="Permalink to “handlers?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>handlers?</strong>: <a href="#worldhandlersfactory"><code>WorldHandlersFactory</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L121" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:121</a></p><p>The handlers each world runs; see <a href="#worldhandlersfactory">WorldHandlersFactory</a>.</p><h5 id="load" tabindex="-1">load? <a class="header-anchor" href="#load" aria-label="Permalink to “load?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>load?</strong>: <code>ReadonlyMap</code>&lt;<code>string</code>, <a href="#dimensionload"><code>DimensionLoad</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L104" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:104</a></p><p>When each stem&#39;s world is built, by dimension id. A stem left out is <code>lazy</code>.</p><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h5><blockquote><p><code>readonly</code> <strong>name</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L83" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:83</a></p><p>The folder name under <code>worlds/</code>, which is also the <code>worlds.&lt;name&gt;</code> key.</p><h5 id="onworldbuilt" tabindex="-1">onWorldBuilt? <a class="header-anchor" href="#onworldbuilt" aria-label="Permalink to “onWorldBuilt?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>onWorldBuilt?</strong>: (<code>world</code>) =&gt; <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L127" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:127</a></p><p>Called with each world the level builds, before the world is enabled. Where the owner registers the world and attaches what the world must not build itself, such as its change sink.</p><h6 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="world" tabindex="-1">world <a class="header-anchor" href="#world" aria-label="Permalink to “world”">​</a></h6><p><a href="./../World/classes/World.html"><code>World</code></a></p><h6 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h6><p><code>void</code></p><h5 id="path" tabindex="-1">path <a class="header-anchor" href="#path" aria-label="Permalink to “path”">​</a></h5><blockquote><p><code>readonly</code> <strong>path</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L85" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:85</a></p><p>The level folder, where the legacy <code>level.json</code> and the fallback player records live.</p><h5 id="provider" tabindex="-1">provider <a class="header-anchor" href="#provider" aria-label="Permalink to “provider”">​</a></h5><blockquote><p><code>readonly</code> <strong>provider</strong>: <code>BaseProvider</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L89" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:89</a></p><p>The one provider for every dimension of this save. The level opens and closes it.</p><h5 id="seed" tabindex="-1">seed <a class="header-anchor" href="#seed" aria-label="Permalink to “seed”">​</a></h5><blockquote><p><code>readonly</code> <strong>seed</strong>: <code>bigint</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L91" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:91</a></p><p>The world seed, as a 64-bit value. See import(&#39;../utils/Seed&#39;).worldSeedOf.</p><h5 id="server" tabindex="-1">server <a class="header-anchor" href="#server" aria-label="Permalink to “server”">​</a></h5><blockquote><p><code>readonly</code> <strong>server</strong>: <a href="./../../Server/classes/Server.html"><code>Server</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L87" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:87</a></p><p>The server the level belongs to. The level reads its content and logger and hands it to each world it builds.</p><h5 id="stems" tabindex="-1">stems <a class="header-anchor" href="#stems" aria-label="Permalink to “stems”">​</a></h5><blockquote><p><code>readonly</code> <strong>stems</strong>: <code>ReadonlyMap</code>&lt;<code>string</code>, <a href="./../../../worldgen/#levelstem"><code>LevelStem</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L96" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:96</a></p><p>The resolved level stems, keyed by dimension id such as <code>minecraft:the_nether</code>, in the order a custom type gets its Bedrock id. Has to carry <code>minecraft:overworld</code>.</p><h5 id="terraincache" tabindex="-1">terrainCache? <a class="header-anchor" href="#terraincache" aria-label="Permalink to “terrainCache?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>terrainCache?</strong>: <a href="./../GeneratorFactories/#terraincachesettings"><code>TerrainCacheSettings</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L117" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:117</a></p><p>The terrain tile cache from server configuration, forwarded to generator factories.</p><h5 id="worldgen" tabindex="-1">worldgen? <a class="header-anchor" href="#worldgen" aria-label="Permalink to “worldgen?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>worldgen?</strong>: () =&gt; <code>JavaWorldgenRegistries</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L111" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:111</a></p><p>Java&#39;s world generation registries, read when a stem&#39;s factory asks for them. Defaults to the Java data cache on disk, which a flat or void level never touches.</p><h6 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h6><p><code>JavaWorldgenRegistries</code></p><h2 id="type-aliases" tabindex="-1">Type Aliases <a class="header-anchor" href="#type-aliases" aria-label="Permalink to “Type Aliases”">​</a></h2><h3 id="dimensionload" tabindex="-1">DimensionLoad <a class="header-anchor" href="#dimensionload" aria-label="Permalink to “DimensionLoad”">​</a></h3><blockquote><p><strong>DimensionLoad</strong> = <code>&quot;eager&quot;</code> | <code>&quot;lazy&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L65" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:65</a></p><p>When a stem&#39;s world is built: at <a href="./classes/Level.html#enable">Level.enable</a>, or on the first <a href="./classes/Level.html#world">Level.world</a>.</p><hr><h3 id="worldhandlersfactory" tabindex="-1">WorldHandlersFactory <a class="header-anchor" href="#worldhandlersfactory" aria-label="Permalink to “WorldHandlersFactory”">​</a></h3><blockquote><p><strong>WorldHandlersFactory</strong> = (<code>world</code>, <code>dimension</code>) =&gt; <code>Pick</code>&lt;<a href="./../World/#worlddata"><code>WorldData</code></a>, <code>&quot;randomTickHandlers&quot;</code> | <code>&quot;blockTickHandlers&quot;</code> | <code>&quot;redstoneUpdateHandlers&quot;</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/world/Level.ts#L75" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:75</a></p><p>The handlers a level&#39;s worlds run, built per world by whoever owns the content.</p><p>A world&#39;s random tick, scheduled tick and redstone handlers are closures over the world they run in, and the world does not exist until the level builds it. The level calls this with a thunk that answers the world once it is built, which is how <code>WorldManager</code> has always built them.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="world-1" tabindex="-1">world <a class="header-anchor" href="#world-1" aria-label="Permalink to “world”">​</a></h5><p>() =&gt; <a href="./../World/classes/World.html"><code>World</code></a> | <code>undefined</code></p><h5 id="dimension" tabindex="-1">dimension <a class="header-anchor" href="#dimension" aria-label="Permalink to “dimension”">​</a></h5><p><code>DimensionType</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Pick</code>&lt;<a href="./../World/#worlddata"><code>WorldData</code></a>, <code>&quot;randomTickHandlers&quot;</code> | <code>&quot;blockTickHandlers&quot;</code> | <code>&quot;redstoneUpdateHandlers&quot;</code>&gt;</p>`,98)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};